package org.light.challenge.core.agent.models

import ai.koog.agents.core.tools.annotations.LLMDescription
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Action model for LLM structured data generation.
 * Used to represent actions that should be generated by the LLM.
 */
@Serializable
@SerialName("LLMAction")
@LLMDescription("Action to be executed as part of a workflow rule")
data class LLMAction(
    @property:LLMDescription("Unique identifier for the action type (e.g., 'send-email', 'send-slack')")
    val id: String,
    
    @property:LLMDescription("Parameters for the action as key-value pairs")
    val parameters: Map<String, String>
) 